INSERT INTO EMAIL_VERIFICATION_REQUEST (
    request_id, flow_trace_id, user_idx, purpose, pending_email, token, status,
    requested_at, expired_at, ip_address, user_agent
) VALUES (
    #{requestId}, #{flowTraceId}, #{userIdx}, #{purpose}, #{pendingEmail}, #{token}, #{status},
    NOW(), #{expiredAt}, #{ipAddress}, #{userAgent}
)

mapper.select:
SELECT *
FROM EMAIL_VERIFICATION_REQUEST
WHERE user_idx = #{userIdx}
  AND request_id = #{requestId}
  AND purpose = #{purpose}
  AND pending_email = #{pendingEmail}
  AND status = 'VERIFIED'
  AND expired_at > NOW()
  AND applied_at IS NULL
  AND cancelled_at IS NULL
ORDER BY verified_at DESC, email_verification_request_idx DESC
LIMIT 1

SELECT *
FROM EMAIL_VERIFICATION_REQUEST
WHERE user_idx = #{userIdx}
  AND request_id = #{requestId}
  AND purpose = #{purpose}
  AND pending_email = #{pendingEmail}
  AND cancelled_at IS NULL
ORDER BY email_verification_request_idx DESC
LIMIT 1

