INSERT INTO EMAIL_VERIFICATION (
    email_verification_request_idx, request_id, flow_trace_id, user_idx, email, token, purpose, expired_at,
    used, used_at, cancelled_at
) VALUES (
    #{emailVerificationRequestIdx}, #{requestId}, #{flowTraceId}, #{userIdx}, #{email}, #{token}, #{purpose}, #{expiredAt},
    FALSE, #{usedAt}, #{cancelledAt}
)

mapper.select:
SELECT * FROM EMAIL_VERIFICATION
WHERE token      = #{token}
  AND purpose    = #{purpose}
  AND used       = FALSE
  AND expired_at > NOW()
LIMIT 1

mapper.update:
UPDATE EMAIL_VERIFICATION
SET expired_at = NOW()
WHERE email   = #{email}
  AND purpose = #{purpose}
  AND used    = FALSE
